{
  "documents": [
    {
      "type": "text",
      "data": "ROOFING SERVICES AGREEMENT\nLimited Warranty: 10 years from 2026-03-14."
    }
  ],
  "criteria": [
    {
      "name": "Limited Warranty",
      "type": "text"
    },
    {
      "name": "contract date",
      "type": "text",
      "options": {
        "match": "regex",
        "pattern": "\\d{4}-\\d{2}-\\d{2}"
      }
    },
    {
      "name": "mentions a warranty period",
      "type": "llm",
      "options": {
        "hint": "presence"
      }
    }
  ]
}

{
  "documents": [
    {
      "type": "base64",
      "data": "{{invoice_native_b64}}",
      "filename": "invoice_native.pdf"
    },
    {
      "type": "url",
      "data": "https://example.com/site_photo.jpg"
    },
    {
      "type": "text",
      "data": "NOTICE TO OWNER — Under Florida law, those who work on your property…"
    }
  ],
  "criteria": [
    {
      "name": "Notice to Owner",
      "type": "text",
      "options": {
        "match": "fuzzy"
      }
    },
    {
      "name": "Notice to Owner in every document",
      "type": "text",
      "options": {
        "pattern": "Notice to Owner",
        "match": "fuzzy",
        "aggregate": {
          "documents": "all"
        }
      }
    },
    {
      "name": "has a signature",
      "type": "llm",
      "options": {
        "hint": "presence",
        "aggregate": {
          "pages": "any",
          "documents": "any"
        }
      }
    },
    {
      "name": "sharpness",
      "type": "cv"
    }
  ]
}

{
  "document": {
    "type": "base64",
    "data": "{{invoice_native_b64}}",
    "filename": "invoice_native.pdf"
  },
  "page": 0,
  "criteria": [
    {
      "name": "has a company logo",
      "type": "llm",
      "options": {
        "hint": "presence"
      }
    },
    {
      "name": "a roof",
      "type": "llm",
      "options": {
        "hint": "presence"
      }
    }
  ],
  "breakdown": {
    "has a company logo": {
      "score": 10,
      "reason": "the logo, top left"
    }
  },
  "regions": {
    "has a company logo": [
      {
        "box": [
          40,
          30,
          320,
          140
        ]
      }
    ]
  },
  "region_units": "grid",
  "title": "Native invoice, logo top left",
  "tags": [
    "invoices",
    "acme"
  ]
}
